int
tiku_draw_text(tiku_draw_window_t *win, int x, int y, uint32_t colour, tiku_draw_face_t face, const char *text)
{
    size_t tail = (text != NULL) ? strlen(text) + 1u : 1u;
    unsigned char *p = tiku_draw_op_begin(win, 6u, 9u + tail);
    size_t at = 9u;

    if (p == NULL) {
        return 0;
    }
    tiku_draw_put16(p + 0, x);
    tiku_draw_put16(p + 2, y);
    tiku_draw_put32(p + 4, colour);
    p[8] = (unsigned char)face;
    memcpy(p + at, text ? text : "", tail);
    (void)at;
    return 1;
}

